#include "cloudmoon_client.h"
#include "cloudmoon_protocol.h"
#include "cloudmoon_ws.h"
#include <stdio.h>
#include <string.h>
#define CM_CLIENT_PACKET_MAX 8192
static int cm_client_send_event(cm_cloudmoon_client_t*c,const char*p,size_t n){return c->send?c->send(c->send_context,p,n):-1;}
void cm_cloudmoon_client_init(cm_cloudmoon_client_t*c,const cm_cloudmoon_registration_t*r,cm_cloudmoon_send_fn send,cm_cloudmoon_signal_fn signal,void*send_ctx,void*signal_ctx){if(!c)return;memset(c,0,sizeof(*c));cm_session_init(&c->session);if(r)c->registration=*r;c->send=send;c->signal=signal;c->send_context=send_ctx;c->signal_context=signal_ctx;}
cm_client_packet_result_t cm_cloudmoon_client_handle_packet(cm_cloudmoon_client_t*c,const char*packet,size_t length){char out[4096],copy[CM_CLIENT_PACKET_MAX+1];int n;cm_sio_event_t ev;cm_session_action_t action;if(!c||!packet||!length||length>CM_CLIENT_PACKET_MAX)return CM_CLIENT_PACKET_ERROR;memcpy(copy,packet,length);copy[length]=0;
if(copy[0]=='0'){if(length>1&&copy[1]=='{')return cm_client_send_event(c,"40",2)<0?CM_CLIENT_PACKET_ERROR:CM_CLIENT_PACKET_CONTINUE;return CM_CLIENT_PACKET_ERROR;}
if(copy[0]=='2'){if(length>=sizeof(out))return CM_CLIENT_PACKET_ERROR;out[0]='3';if(length>1)memcpy(out+1,copy+1,length-1);out[length]=0;return cm_client_send_event(c,out,length)<0?CM_CLIENT_PACKET_ERROR:CM_CLIENT_PACKET_CONTINUE;}
if(length>=2&&copy[0]=='4'&&copy[1]=='0'){c->session.state=CM_SESSION_SOCKET_CONNECTED;return CM_CLIENT_PACKET_CONTINUE;}
if(length>=2&&copy[0]=='4'&&copy[1]=='1'){c->session.state=CM_SESSION_CLOSED;return CM_CLIENT_PACKET_STOP;}
if(length>=2&&copy[0]=='4'&&copy[1]=='2'){if(cm_socketio_parse_event(copy,&ev)!=0)return CM_CLIENT_PACKET_ERROR;action=cm_session_on_event(&c->session,&ev);switch(action){case CM_SESSION_ACTION_SEND_CLIENT_REGISTER:n=cm_socketio_make_client_register(out,sizeof(out),c->registration.width,c->registration.height,c->registration.game,c->registration.user_id,c->registration.instance_id);if(n<0)return CM_CLIENT_PACKET_ERROR;return cm_client_send_event(c,out,(size_t)n)<0?CM_CLIENT_PACKET_ERROR:CM_CLIENT_PACKET_CONTINUE;case CM_SESSION_ACTION_SEND_REGISTER:n=cm_socketio_make_register(out,sizeof(out),c->session.room_id,c->session.client_id);if(n<0)return CM_CLIENT_PACKET_ERROR;return cm_client_send_event(c,out,(size_t)n)<0?CM_CLIENT_PACKET_ERROR:CM_CLIENT_PACKET_CONTINUE;case CM_SESSION_ACTION_HANDLE_SIGNAL:if(c->signal)c->signal(c->signal_context,ev.payload,ev.payload_len);return CM_CLIENT_PACKET_CONTINUE;case CM_SESSION_ACTION_STOP:return CM_CLIENT_PACKET_STOP;default:return c->session.state==CM_SESSION_ERROR?CM_CLIENT_PACKET_ERROR:CM_CLIENT_PACKET_IGNORED;}}
if(copy[0]=='1'){c->session.state=CM_SESSION_CLOSED;return CM_CLIENT_PACKET_STOP;}return CM_CLIENT_PACKET_IGNORED;}
typedef struct{cm_ws_tls_transport*transport;cm_random_source_fn rng;void*rng_ctx;} cm_client_transport_context;
static int cm_client_transport_send(void*ctx,const char*p,size_t n){cm_client_transport_context*t=(cm_client_transport_context*)ctx;return cm_ws_tls_send(t->transport,CM_WS_TEXT,1,p,n,t->rng,t->rng_ctx);}
int cm_cloudmoon_client_run(const char*host,uint16_t port,const char*path,const char*ca,unsigned timeout,const cm_cloudmoon_registration_t*r,cm_random_source_fn rng,void*rng_ctx,cm_cloudmoon_signal_fn signal,void*signal_ctx){cm_ws_tls_transport*t=NULL;cm_cloudmoon_client_t c;cm_client_transport_context tx;cm_ws_frame_info_t info;uint8_t payload[CM_CLIENT_PACKET_MAX];int rc=-1;if(!r||!rng)return -1;if(cm_ws_tls_connect(&t,host,port,path,ca,timeout,rng,rng_ctx)!=0)return -1;tx.transport=t;tx.rng=rng;tx.rng_ctx=rng_ctx;cm_cloudmoon_client_init(&c,r,cm_client_transport_send,signal,&tx,signal_ctx);for(;;){int n=cm_ws_tls_read_frame(t,&info,payload,sizeof(payload));if(n<0)break;if(info.opcode==CM_WS_CLOSE){rc=0;break;}if(info.opcode==CM_WS_PING){if(cm_ws_tls_send(t,CM_WS_PONG,1,payload,info.payload_len,rng,rng_ctx)<0)break;continue;}if(info.opcode==CM_WS_PONG)continue;if(info.opcode!=CM_WS_TEXT||!info.fin)continue;{cm_client_packet_result_t pr=cm_cloudmoon_client_handle_packet(&c,(const char*)payload,info.payload_len);if(pr==CM_CLIENT_PACKET_ERROR)break;if(pr==CM_CLIENT_PACKET_STOP){rc=0;break;}}}cm_ws_tls_close(t);return rc;}
